"""Summarize node JSONL sequences without changing the node."""
import json
import os
import re
import stat
import sys
from collections import Counter


def _invalid_constant(value):
    raise ValueError(value)


def _json(data):
    return json.loads(data, parse_constant=_invalid_constant)


def _channel(folder, channel, bad):
    pattern = re.compile(re.escape(channel) + r"\.([0-9]{12})\.jsonl\Z")
    segments = []
    active = None
    with os.scandir(folder) as entries:
        for entry in entries:
            if not entry.is_file(follow_symlinks=False):
                continue
            match = pattern.fullmatch(entry.name)
            if match:
                segments.append((int(match.group(1)), entry.name))
            elif entry.name == channel + ".active.jsonl":
                active = entry.name
    filenames = [name for _, name in sorted(segments)]
    if active is not None:
        filenames.append(active)

    sequences = []
    for filename in filenames:
        with open(os.path.join(folder, filename), "rb") as stream:
            lines = stream.read().split(b"\n")
        for number, line in enumerate(lines[:-1], 1):
            try:
                record = _json(line)
            except (ValueError, UnicodeError):
                bad.append({"file": filename, "line": number, "why": "bad_json"})
                continue
            seq = record.get("seq") if isinstance(record, dict) else None
            if type(seq) is not int or seq < 1:
                bad.append({"file": filename, "line": number, "why": "no_seq"})
            else:
                sequences.append(seq)
        if lines[-1]:
            bad.append({"file": filename, "line": len(lines), "why": "torn"})

    counts = Counter(sequences)
    ordered = sorted(counts)
    return {
        "count": len(sequences),
        "first": ordered[0] if ordered else None,
        "last": ordered[-1] if ordered else None,
        "missing": [[left + 1, right - 1] for left, right in zip(ordered, ordered[1:]) if right > left + 1],
        "dup": sorted(seq for seq, count in counts.items() if count >= 2),
        "next_seq": None,
        "unacked": None,
        "stale_next": None,
    }, counts


def _state(folder, channels, counts, bad):
    path = os.path.join(folder, "state.json")
    try:
        mode = os.stat(path, follow_symlinks=False).st_mode
    except FileNotFoundError:
        return
    except OSError:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
        return
    try:
        if not stat.S_ISREG(mode):
            raise ValueError("state is not a regular file")
        with open(path, "rb") as stream:
            state = _json(stream.read())
    except (OSError, ValueError, UnicodeError):
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
        return
    if not isinstance(state, dict) or not isinstance(state.get("channels"), dict):
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
        return

    invalid = False
    for channel in ("obs", "must"):
        data = state["channels"].get(channel)
        if (not isinstance(data, dict) or type(data.get("next_seq")) is not int
                or (channel == "must" and type(data.get("acked_upto")) is not int)):
            invalid = True
            continue
        result = channels[channel]
        result["next_seq"] = data["next_seq"]
        result["stale_next"] = (data["next_seq"] != result["last"] + 1) if result["last"] is not None else None
        if channel == "must":
            result["unacked"] = sum(seq > data["acked_upto"] for seq in counts[channel])
    if invalid:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})


def summarize(folder):
    bad = []
    channels = {}
    counts = {}
    for channel in ("obs", "must"):
        channels[channel], counts[channel] = _channel(folder, channel, bad)
    _state(folder, channels, counts, bad)
    bad.sort(key=lambda item: (item["file"], item["line"] if item["line"] is not None else 0, item["why"]))
    return {"v": 1, "channels": channels, "bad": bad}


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    if len(args) != 1 or not os.path.isdir(args[0]):
        return 2
    try:
        result = summarize(args[0])
    except OSError:
        return 2
    print(json.dumps(result, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
